data = [('books',12),('food',8),('books',5),('food',2)]

# Aggregate amounts by category
totals = {}
for cat, amt in data:
    totals[cat] = totals.get(cat, 0) + amt

# Print sorted results
for cat in sorted(totals):
    print(f"{cat}: {totals[cat]}")

# Assert total sum
assert sum(totals.values()) == 27

